/* The Order of 86 — wizard roster: the 86 Doginal Dogs whose Head trait is "Wizard".
 * Each entry: number (Doginal Dog number), name (market name if unique, else null),
 * image (local file), traits ([category, value] pairs), rank (Rarity Rank out of 10,000,
 * from market.doginaldogs.com; 1 = rarest), title, order (Flame/Wild/Arcane/Deep/Radiant/
 * Dream/Wanderer), realm and lore (paragraphs split by a blank line; *x* = emphasis).
 * Lore text is Defi's writing, copied as text only. Holder X handles live in js/holders.js.
 * Order: Dog #6164 (The Wanderer) first, then by market Rarity Rank ascending (rarest first).
 * Do NOT add wallet addresses, inscription IDs, holder handles or prices here.
 */
window.WIZARDS = [
    {"number": 6164, "name": null, "image": "images/dogs/6164.png", "traits": [["Background", "Tan"], ["Fur Color", "Gray"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Round Glasses"]], "rank": 7277, "title": "The Wanderer", "lore": "The most ordinary-looking dog in the collection. Gray fur. Classic pattern. No clothes. No accessories. Round glasses. Rank 7,277, deep in the bottom quartile of rarity. By every objective metric, unremarkable. Except for one detail visible only in the art: his hat is pointy. Every other Wizard's hat is rounded or folded. The Wanderer's hat ends in a sharp point, the classic wizard's hat from legend.\n\nIn the devotional origin tradition, he is the First Dog: the being who appeared in the emptiness before existence and howled the universe into being. His story is the origin story every pup in Pawtheon knows by heart: alone in the void, he sat patiently until patience became purpose, then opened his mouth and sang reality into existence with the First Howl. Seven tones, seven moons, seven realms, and everything that followed.\n\nHis hat is purple, the color of the Arcane, but he is not Arcane. The thirteen Arcane Wizards do not include him in their count; fourteen purple hats exist only when his distinct channel is included. His hat resonates with all six Order frequencies simultaneously and with Palehowl, the Starter Moon, the weakest of the seven. He draws his power not from the concentrated magic of the Orders but from the diffuse magic that touches every common dog in Pawtheon. During the Septenary Alignment, when all seven moons are full, Palehowl blazes brighter than all six Order Moons combined, and the humblest magic becomes the strongest.\n\nHe walks. Between realms, between Orders, between the breed-world and the moon-world. He tells stories, especially his own, the tale of the First Howl. He sits patiently in places where patience is needed. He howls sometimes, late at night, when the seven moons align. And when he does, every dog in Pawtheon stops what they're doing and listens.\n\nThe Wanderer was offered leadership of the 86 after the Loyalty Wars. He refused. He was offered membership in the Arcane Order because his hat is purple. He refused. He was offered a home in the Violet Highlands because he's a Classic. He refused. He doesn't lead because leading would require choosing sides, and the dog who howled everything into existence doesn't take sides. He takes walks.\n\nThat same tradition holds that the round glasses he wears are the same glasses he wore in the void before creation, artifacts from before artifacts existed, lenses that have seen the birth of everything. They're not magic. They're more than magic. They're the first objects that ever existed, created by the need to see clearly in a universe that didn't yet have light.\n\nHis rank, 7,277, marks him as common. His power marks him as unique. The contradiction is the point. The First Howl never ended. It just became too quiet for most to hear. But The Wanderer still hears it, still carries it, still *is* it. When the next crisis comes, and the Deep know it's coming, though they won't say what it is, the most ordinary dog will once again become the most extraordinary being in the Caninsphere.\n\nHe is the 86th Wizard, inside the Order of 86 but outside every Order within it. He started everything. He belongs to nothing. And that's exactly how it should be.\n\nThese cosmic-origin claims are attributed traditions. They do not erase the archaeological pre-Howl world or establish a known birth date.", "summary": "Also called the Gray Dog. The unaffiliated 86th wizard, whose howl woke the seven moons. Palehowl is the Wanderer's moon.", "epithet": "First Dog, Author of the First Howl", "order": "Wanderer", "realm": "No fixed realm"},
    {"number": 9089, "name": null, "image": "images/dogs/9089.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Clothes", "Tracksuit"], ["Mouth", "Ball"], ["Eyes", "Red"]], "rank": 46, "title": "The Warlock", "order": "Dream", "realm": "Abyssal Reaches", "lore": "The rarest Wizard in the Order of 86. The rarest Wizard in the entire Doginal Dogs collection. And they're a Somnambulist. A Black Split from the Abyssal Reaches, the realm of duality and impossible perspectives, wearing a Tracksuit (one of the very few clothed Wizards) and carrying a Ball (unique among all 86). Red eyes in a black face, the rarest eye color combined with the starkest fur contrast.\n\nThe Warlock's incredible rarity translates to raw magical potential that terrifies even experienced Wizards. When they join a pack cast, the multiplicative effect of Dream magic reaches levels that could reshape reality itself. Their Red eyes, the rarest eye color among the Wizards, see dream-threads as physical threads, visible and tangible as rope or wire. Their Split heritage lets them experience multiple oneiroic perspectives simultaneously, while their black fur absorbs and concentrates oneiroic energy from everyone around them.\n\nThe Tracksuit marks them as deliberately casual, rejecting the solemnity that most Wizards affect. The Ball suggests playfulness, youth, or perhaps the wisdom to remember that joy is the highest form of love. Their presence at the Dream Spire makes the entire structure pulse stronger, and their subconscious range, from childlike wonder to cosmic subconscious sight, drives their Order-mates to heights of magical power they never imagined possible. The most powerful entity in the Caninsphere carries a ball and wears a tracksuit. That's not a contradiction, that's the point."},
    {"number": 9684, "name": null, "image": "images/dogs/9684.png", "traits": [["Background", "Tan"], ["Fur Color", "White"], ["Fur Pattern", "Blotted"], ["Head", "Wizard"], ["Clothes", "Shirt"], ["Mouth", "Bone"], ["Eyes", "Yellow"]], "rank": 66, "title": "Goldblot the Luminous Shadow", "order": "Radiant", "realm": "Shadowmire", "lore": "The rarest Radiant Wizard and the greatest paradox in the Order. A Blotted from the dark Shadowmire practicing the magic of absolute light. Goldblot's white base color with chaotic dark blotting creates the perfect canvas for light magic, the blots absorb and concentrate solar energy while the white fur reflects and amplifies it. Their yellow eyes match their Order's color perfectly, while the shirt they wear is woven from light-capturing fibers that glow softly in darkness.\n\nTheir magic is Shadow-Light Synthesis, using darkness to define light, creating illumination that is only visible in contrast to shadow, and purifying corruption by burning it away from the inside. Goldblot's blotted pattern shifts to concentrate light magic in the most effective configurations, while their Shadowmire heritage makes them immune to the corruption they're fighting. They serve as the Radiant's specialist in corruption purification, proving that sometimes the best weapon against darkness is light that understands shadow."},
    {"number": 9604, "name": null, "image": "images/dogs/9604.png", "traits": [["Background", "Tan"], ["Fur Color", "Beige"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Lumberjack"], ["Mouth", "Bone"], ["Eyes", "Black"]], "rank": 277, "title": "Beigelumber the Worker's Light", "order": "Radiant", "realm": "Violet Highlands", "lore": "A working-class Classic whose beige fur and lumberjack outfit mark them as different from the typical scholarly atmosphere of both their home realm and their Order. Beigelumber earned their yellow hat not through theoretical study but through practical application, using light magic to guide rescue operations in collapsed buildings, providing illumination for emergency medical procedures, and creating light-based tools for construction work.\n\nTheir magic is Practical Radiance, light that serves immediate, useful purposes rather than dramatic displays. Beigelumber's solar magic focuses into precise tools: light-blades for cutting, light-ropes for lifting, light-shields for protection. Their lumberjack background means they understand that the best magic is magic that gets work done. They serve as the Radiant's specialist in utility magic, proving that purification and revelation can be as simple as providing light when people need to see clearly."},
    {"number": 8518, "name": null, "image": "images/dogs/8518.png", "traits": [["Background", "Purple"], ["Fur Color", "Black"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Mouth", "Ball"], ["Eyes", "Yellow"]], "rank": 407, "title": "Goldstripe the Time Stalker", "order": "Dream", "realm": "Ember Wastes", "lore": "The second-rarest Dream Wizard, a solitary Tiger whose hunting instincts evolved into something far more sophisticated: tracking dream-threads through time itself. Goldstripe's black fur with golden stripes creates perfect camouflage in the shifting light-and-shadow patterns of dream magic, while their yellow eyes see not just heat signatures but oneiroic signatures, the traces left by past and future events. They earned their magenta hat by successfully tracking and observing the same historical moment from seventeen different temporal angles.\n\nTheir specialty is Temporal Archaeology, using time-sight magic to witness past events and gather information that was lost to conventional history. Goldstripe hunts lost knowledge the way other Tigers hunt prey, following temporal trails through layered time until they find the moment when crucial information was hidden or destroyed. They serve as the Dream's historical dream-tracker, solving mysteries that have been forgotten for centuries. Their solitary nature is perfect for time-diving, since temporal magic works best when practiced alone to avoid paradox complications."},
    {"number": 9469, "name": null, "image": "images/dogs/9469.png", "traits": [["Background", "Yellow"], ["Fur Color", "White"], ["Fur Pattern", "Blotted"], ["Head", "Wizard"], ["Mouth", "Chicken"], ["Eyes", "Sleepy"]], "rank": 464, "title": "Whitemist the Sleepy Purifier", "order": "Radiant", "realm": "Shadowmire", "lore": "The second Shadowmire Wizard in the Radiant Order, but where Goldblot works with shadow-light synthesis, Whitemist specializes in gentle purification that works while the patient sleeps. Their white base color with soft blotting creates perfect channels for healing light, while their permanently sleepy appearance reflects their specialty in unconscious purification magic.\n\nTheir magic is Dream Purification, cleansing corruption, fear, and negative subconscious currents while the subject sleeps, removing magical contamination without the pain that conscious purification causes, and healing trauma through gentle dream-light therapy. Whitemist's sleepy nature allows them to work in dream states where purification magic is more effective and less traumatic. They serve as the Radiant's medical specialist, providing healing that works through rest and gentle revelation rather than dramatic intervention."},
    {"number": 8728, "name": null, "image": "images/dogs/8728.png", "traits": [["Background", "Aqua"], ["Fur Color", "Gray"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Clothes", "Scarf"], ["Eyes", "Square Glasses"]], "rank": 554, "title": "Frostforge the Scarf Bearer", "lore": "The rarest Flame Wizard, and the greatest contradiction in the Order. A Husky from Frosthollow's deepest glaciers, wielding fire magic with scholarly precision. The orange hat found Frostforge during the worst blizzard in Frosthollow's recorded history. While other dogs sought shelter, they stood alone on an exposed peak, reading by the faint aurora light, not seeking warmth, but studying the mathematics of cold. When the hat manifested in the storm, wreathed in flame that never touched their scarf, it chose not courage over fear, but curiosity over comfort.\n\nFrostforge brings the analytical mind of ice to the explosive art of fire. Their signature technique, Measured Burn, creates flames that burn only what needs burning, no more, no less. The scarf they wear isn't fashion; it's a reminder that some heat must be contained to be useful. They are the Flame's chief theoretical researcher, developing new forms of forge magic through the marriage of Frosthollow's patience and Emberhowl's power. Other Flame Wizards charge into battle; Frostforge calculates the exact temperature needed to end it.", "order": "Flame", "realm": "Frosthollow"},
    {"number": 3449, "name": null, "image": "images/dogs/3449.png", "traits": [["Background", "Blue"], ["Fur Color", "Brown"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Clothes", "Poncho"], ["Eyes", "Pink"]], "rank": 627, "title": "Stripeheart the Bridge Walker", "order": "Wild", "realm": "Ember Wastes", "lore": "The rarest Wild Wizard and the greatest contradiction in the Order. A solitary Tiger from the volcanic Ember Wastes, where independence is survival, who found their green hat by doing the most un-Tiger thing possible: they established a permanent beast sanctuary. Stripeheart's pink eyes, the gift of oneiroic sight, let them see the terror in animals fleeing volcanic eruptions. Instead of hunting prey weakened by disaster, they guided them to safety. The green hat manifested as they stood between a pack of terrified creatures and a lava flow, using their own body as a bridge to guide them across cooling stone.\n\nTheir poncho, woven from plant fibers that grow only in volcanic soil, marks them as a traveler between realms. Stripeheart carries seeds from the Heartwood throughout the Ember Wastes, creating networks of green growth in the most unlikely places. They are the Wild's ambassador to the Tiger realm, proving that solitary creatures can serve collective good without losing their essential nature. When natural disasters threaten to separate mothers from cubs, Stripeheart creates magical migration routes that keep families together. Their pink eyes weep for every creature they cannot save, and their tears grow into memorial gardens."},
    {"number": 4165, "name": null, "image": "images/dogs/4165.png", "traits": [["Background", "Red"], ["Fur Color", "White"], ["Fur Pattern", "Collie"], ["Head", "Wizard"], ["Clothes", "Poncho"], ["Eyes", "Pink"]], "rank": 854, "title": "Pearlgaze the Emotional Seer", "order": "Deep", "realm": "Deepwood", "lore": "Pearlgaze drifts through the Deepwood like a ghost in a woven poncho, their white Collie fur luminous against the dark undergrowth. Those pink eyes perceive the oneiroic spectra that radiate from all sentient beings, visible as colored halos only Pearlgaze can read. The poncho was a gift from a grieving hermit whose sorrow Pearlgaze dissolved without a single word spoken. As a Deep Order mage, Pearlgaze plumbs the hidden oneiroic currents beneath conscious thought, surfacing truths that the mind buries but the heart remembers."},
    {"number": 3406, "name": null, "image": "images/dogs/3406.png", "traits": [["Background", "Tan"], ["Fur Color", "Yellow"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Clothes", "Shirt"], ["Eyes", "Blue"]], "rank": 912, "title": "Pinkmantle the Dimensional Scholar", "order": "Arcane", "realm": "Sunward Heights", "lore": "In the sun-drenched libraries of the Sunward Heights, Pinkmantle pores over manuscripts that exist in three dimensions simultaneously. Their yellow Solid coat catches the golden light that pours through crystalline windows, and the shirt they wear , threadbare, ink-stained, beloved , has pockets that open into other planes of study. Those piercing blue eyes can read text written in languages that haven't been invented yet. Pinkmantle is the Arcane Order's foremost theorist on dimensional overlap, having proven that certain ideas are so powerful they bleed through the walls between worlds."},
    {"number": 7833, "name": null, "image": "images/dogs/7833.png", "traits": [["Background", "Yellow"], ["Fur Color", "Bronze"], ["Fur Pattern", "Shiny"], ["Head", "Wizard"], ["Clothes", "Sport Hoodie"], ["Eyes", "Black"]], "rank": 1025, "title": "Bronzebeacon the Shiny Light", "order": "Radiant", "realm": "Shadowmire", "lore": "The collection's only Shiny Wizard, making them as unique among the 86 as their breed is among all dogs. Bronzebeacon's metallic bronze fur literally glows with its own light, while their sport hoodie suggests an active, dynamic approach to light magic that matches their role as beacon-keeper in the dark Shadowmire. Their black eyes provide stark contrast to their glowing fur, creating perfect focus for directing concentrated light magic.\n\nTheir specialty is Beacon Magic, creating permanent points of light that guide lost travelers, establishing magical lighthouses that pierce any darkness, and maintaining the illumination network that makes navigation possible in lightless environments. Bronzebeacon's Shiny nature means their light never dims, never flickers, never fails. They serve as the Radiant's most reliable source of constant illumination, proving that some lights burn forever because they were meant to."},
    {"number": 8272, "name": null, "image": "images/dogs/8272.png", "traits": [["Background", "Pink"], ["Fur Color", "White"], ["Fur Pattern", "Spotted"], ["Head", "Wizard"], ["Clothes", "Lumberjack"], ["Eyes", "Round Glasses"]], "rank": 1073, "title": "Spotforge the Pattern Reader", "order": "Wild", "realm": "Deepwood", "lore": "A native of the Deepwood who earned their green hat through the most scholarly form of nature magic: pattern recognition. Spotforge's white coat with dark spots creates a living map of the forest's health, each spot corresponds to a different grove, and the spots' color and size change to reflect the condition of their linked trees. Their round glasses focus not just vision but magical perception, letting them read the deep patterns that connect all growing things.\n\nTheir lumberjack outfit marks them as one of the Wild Order's few members who works with dead wood as well as living trees. Spotforge practices Sustainable Magic, they can tell exactly how much can be taken from a forest without damaging its long-term health. They serve as the Wild's resource manager, ensuring that the Heartwood Spire's growth doesn't drain the surrounding forest. When other Orders need wood for construction, Spotforge selects trees that want to be harvested, usually old trees ready to make room for new growth, transforming their final act into service."},
    {"number": 8822, "name": null, "image": "images/dogs/8822.png", "traits": [["Background", "Tan"], ["Fur Color", "White"], ["Fur Pattern", "Blotted"], ["Head", "Wizard"], ["Clothes", "Sport Hoodie"], ["Eyes", "Square Glasses"]], "rank": 1415, "title": "Chaosbloom the Change Bringer", "order": "Wild", "realm": "Shadowmire", "lore": "From the ever-changing Shadowmire to the ever-growing Heartwood, Chaosbloom brings the gift of controlled chaos to nature magic. Their blotted pattern shifts and changes like the Shadowmire's terrain, never quite the same from day to day. The square glasses they wear focus chaotic energy into readable patterns, while their sport hoodie suggests an active, dynamic approach to magic that matches their homeland's embrace of transformation.\n\nChaosbloom's specialty is Accelerated Evolution, using Wild magic to speed up natural selection and adaptation processes. When the Great Rot threatens specific plant species, they help those plants develop resistance in days instead of generations. Their white base color reflects all forms of magical energy, making them immune to corruption while their chaotic blotting pattern adapts their magic to any challenge. They serve as the Wild's specialist in fighting magical corruption through biological innovation, sometimes the best defense against unnatural evil is natural change happening unnaturally fast."},
    {"number": 5035, "name": null, "image": "images/dogs/5035.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Clothes", "Scarf"], ["Eyes", "Sleepy"]], "rank": 1443, "title": "Blizzardflame the Ice Hearted", "order": "Flame", "realm": "Frosthollow", "lore": "Born during the Great Silence, when all magic died for forty-nine hours, Blizzardflame spent their earliest days in a world without warmth spells or fire magic. They learned to find heat in movement, in purpose, in the friction of determination against impossibility. When magic returned and the orange hat sought them out, it found a Husky who had already discovered that the hottest flame comes from the coldest heart, not from lack of feeling, but from feelings so intense they burn white-hot.\n\nTheir sleepy eyes mask an inner fire that never dims. Blizzardflame practices the most extreme form of Flame discipline: Cold Fire, flames that burn blue-white and feel ice-cold to the touch while melting steel. They serve as the Forge Spire's connection to Frosthollow, carrying messages through blizzards that would kill other messengers. The scarf they wear is woven from their own shed fur, each thread holding a memory of survived cold. When Blizzardflame enters Trial by Fire, the flames turn blue."},
    {"number": 6398, "name": null, "image": "images/dogs/6398.png", "traits": [["Background", "Rose"], ["Fur Color", "Brown"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Clothes", "Shirt"], ["Eyes", "Black"]], "rank": 1466, "title": "Tideseed the Shore Walker", "order": "Wild", "realm": "Abyssal Reaches", "lore": "From the coastal cliffs where land meets sea, Tideseed brings the rhythm of tides to the patience of growth. Their Split nature, half earth-brown, half sea-blue, makes them natural ambassadors between terrestrial plants and marine ecosystems. The shirt they wear is woven from kelp fibers, creating clothing that breathes with the tide's rhythm. Their green hat manifested as they successfully grafted land plants onto underwater root systems, creating the first truly amphibious forest.\n\nTheir magic specializes in Tidal Growth, plants that flourish in both salt and fresh water, roots that grow stronger when submerged, seeds that use wave action to spread. Tideseed maintains the coastal forests that protect inland areas from storm damage, creating living breakwaters that grow stronger with each storm they survive. They serve as liaison between the Wild Order and the Abyssal Reaches, ensuring that both realm interests are served when nature magic affects coastal areas."},
    {"number": 9530, "name": null, "image": "images/dogs/9530.png", "traits": [["Background", "Rose"], ["Fur Color", "White"], ["Fur Pattern", "Bernard"], ["Head", "Wizard"], ["Clothes", "Shirt"], ["Eyes", "Black"]], "rank": 2023, "title": "Bernardguard the Truth Keeper", "order": "Deep", "realm": "Frosthollow", "lore": "The collection's only Bernard Wizard, embodying the perfect convergence of breed instinct and Order discipline. Bernards are the rescue breed, built for finding lost travelers in hostile conditions, carrying supplies to sustain life in crisis. Bernardguard earned their blue hat by successfully guiding a lost expedition through a blizzard to the Truth Mirror's location, then standing guard as each member looked into the mirror and faced what they truly were. Three members never spoke again. Two emerged transformed. One thanked Bernardguard and walked into the snow, never to be seen again.\n\nTheir magic is Guardian Prophecy, seeing the dangerous truths that people seek and determining whether they're strong enough to survive the knowledge they want. Bernardguard maintains permanent station at Frosthollow, serving as the final filter between seekers and the Truth Mirror. Their white fur provides camouflage in snow, while their black eyes see the truth-readiness in approaching souls. The shirt they wear carries supplies for those who emerge from the Truth Mirror needing immediate physical and dream support. They have seen more truth than any other being in Pawtheon, yet their Bernard nature keeps them focused on helping others rather than being overwhelmed by knowledge."},
    {"number": 2426, "name": null, "image": "images/dogs/2426.png", "traits": [["Background", "Rose"], ["Fur Color", "White"], ["Fur Pattern", "Blotted"], ["Head", "Wizard"], ["Clothes", "Turtleneck"], ["Eyes", "Black"]], "rank": 2082, "title": "Blotbark the Corruption Fighter", "order": "Wild", "realm": "Shadowmire", "lore": "The second Shadowmire Wizard in the Wild Order, specializing in the fight against the Great Rot. Blotbark's white base color with chaotic dark blotting creates perfect camouflage in partially corrupted forest, they can move through Rot-touched territory undetected by matching their pattern to diseased bark. Their turtleneck provides protection against airborne spores and magical contamination, while their black eyes see corruption as clearly as other Wild Wizards see healthy growth.\n\nTheir unique ability is Rot Reversal, using controlled decay to fight uncontrolled corruption. By accelerating the natural decomposition of infected plant matter, they prevent the Rot from spreading through root networks. Blotbark walks the dangerous border between healthy forest and corrupted wasteland, serving as early warning system and first line of defense. Their Shadowmire heritage makes them comfortable with decay as natural process, while their Wild training provides the growth magic needed to restore cleared areas."},
    {"number": 9396, "name": null, "image": "images/dogs/9396.png", "traits": [["Background", "Yellow"], ["Fur Color", "Tan"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Clothes", "Collar"], ["Eyes", "Black"]], "rank": 2131, "title": "Tancollar the Diplomatic Light", "order": "Radiant", "realm": "Frosthollow", "lore": "A Husky from ice-realm Frosthollow practicing sun magic, another example of the productive tension between breed instinct and Order discipline. Tancollar's tan fur provides earth-tone grounding for solar energy, while their collar is woven from sun-crystal fibers that store daylight for use during Frosthollow's long winter nights. They earned their yellow hat by successfully establishing the first permanent light-beacon in the deepest arctic regions.\n\nTheir magic is Cold Light, solar energy that provides illumination and warmth without the heat that would melt delicate ice formations. Tancollar's Husky endurance makes them ideal for maintaining light-sources in the harshest conditions, while their diplomatic training (suggested by the collar) makes them effective at negotiating agreements between sun-magic and ice-realm cultures. They serve as the Radiant's arctic specialist, bringing light to places where normal solar magic would be either impossible or destructive."},
    {"number": 5381, "name": null, "image": "images/dogs/5381.png", "traits": [["Background", "Pink"], ["Fur Color", "Pink"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Tracksuit"], ["Eyes", "Black"]], "rank": 2521, "title": "Roseclassic the Pink Diplomat", "order": "Radiant", "realm": "Violet Highlands", "lore": "An unusual color for any Order, pink Classic fur creating visual connection to Dream magic while practicing Radiant discipline. Roseclassic's tracksuit marks them as athletic and active, suggesting dynamic rather than contemplative light magic. They earned recognition by developing techniques for Emotional Purification, using light magic to cleanse negative subconscious currents rather than just revealing truth.\n\nTheir magic is Gentle Radiance, purification that heals rather than burns, light that reveals truth gradually rather than blindingly, and illumination that comforts rather than exposes. Roseclassic's pink coloring reflects their specialty in compassionate revelation, showing people their flaws in ways that encourage growth rather than causing shame. They serve as the Radiant's specialist in therapeutic truth-magic, proving that revelation can be kind without being weak."},
    {"number": 1977, "name": null, "image": "images/dogs/1977.png", "traits": [["Background", "Aqua"], ["Fur Color", "Black"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Collar"], ["Eyes", "Green"]], "rank": 2547, "title": "Blackclassic the Network Walker", "order": "Wild", "realm": "Violet Highlands", "lore": "Blackclassic prowls the misty ridgelines of the Violet Highlands with an emerald gaze that sees the invisible threads connecting all living things. The collar around their neck is no decoration , it is a lodestone anchor, humming with the resonance of ley lines beneath the highland soil. Where other Wild mages read wind and root, Blackclassic reads the web of dream-threads between creatures, tracing loyalty and betrayal through the network of life itself. Their black Classic coat blends with the highland shadows at dusk, and those green eyes flare like foxfire when the network pulses with urgent news."},
    {"number": 9234, "name": null, "image": "images/dogs/9234.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Spotted"], ["Head", "Wizard"], ["Clothes", "Scarf"], ["Eyes", "Black"]], "rank": 2843, "title": "Shadowspot the Pattern Keeper", "order": "Arcane", "realm": "Deepwood", "lore": "A Deepwood native whose spotted pattern serves as a living memory storage system. Shadowspot's black base color with dark spots creates patterns that shift and change to record observed information, while their scarf is woven from memory-silk that preserves important conversations in its fibers. They earned their purple hat by demonstrating that their spotted pattern could store and replay visual memories with perfect accuracy, creating a living archive of everything they've witnessed.\n\nTheir specialty is Memory Magic, storing experiences in physical patterns, sharing memories between individuals, and preserving important information in forms that can't be destroyed by conventional means. Each spot on their coat contains a different memory, accessible through touch-based magic that lets others experience past events from Shadowspot's perspective. They serve as the Arcane's living backup system, ensuring that crucial knowledge survives even if physical records are destroyed."},
    {"number": 7731, "name": null, "image": "images/dogs/7731.png", "traits": [["Background", "Yellow"], ["Fur Color", "Beige"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Shirt"], ["Eyes", "Black"]], "rank": 2866, "title": "Beigelight the Steady Illuminator", "order": "Radiant", "realm": "Violet Highlands", "lore": "The second beige Classic in the Radiant Order, but where Beigelumber focuses on practical applications, Beigelight specializes in sustained illumination for scholarly work. Their beige fur provides perfect neutrality for extended magical work, while the shirt they wear contains light-gathering threads that store solar energy for nighttime use.\n\nTheir magic is Scholarly Radiance, steady, reliable light for reading and research, illumination that doesn't interfere with delicate magical experiments, and truth-magic that reveals information gradually rather than overwhelming researchers with sudden insights. Beigelight serves as the Radiant's academic specialist, providing the consistent, reliable light that makes detailed scholarly work possible. Their steady nature makes them ideal for projects requiring years of patient illumination."},
    {"number": 1976, "name": null, "image": "images/dogs/1976.png", "traits": [["Background", "Tan"], ["Fur Color", "Gray"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Clothes", "Collar"], ["Eyes", "Black"]], "rank": 2938, "title": "Frostbark the Ice Grower", "order": "Wild", "realm": "Frosthollow", "lore": "The most unlikely Wild Wizard, a Husky from the frozen realm practicing magic of growth and warmth. Frostbark's gray fur and endurance breeding make them perfectly suited to Frosthollow's harsh conditions, but their green hat chose them for their understanding of life persisting in impossible circumstances. They found their calling tending the few hardy plants that grow in Frosthollow's brief summers, coaxing maximum life from minimal growing seasons.\n\nTheir collar is woven from arctic moss, the only plant that stays green through Frosthollow's winters. Frostbark's magic specializes in Cold Growth, plants that thrive in sub-freezing temperatures, roots that draw nutrients from ice, and growing seasons that extend into winter months. They prove that Wild magic isn't limited to temperate climates by creating food sources that sustain Frosthollow through the longest winters. When other realms' crops fail due to unexpected cold snaps, Frostbark's arctic varieties provide emergency food supplies."},
    {"number": 9758, "name": null, "image": "images/dogs/9758.png", "traits": [["Background", "Pink"], ["Fur Color", "Tan"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Classic Hoodie"], ["Eyes", "Black"]], "rank": 2989, "title": "Commonflame the Everyman", "order": "Flame", "realm": "Violet Highlands", "lore": "The most politically savvy Flame Wizard, and perhaps the most important. A Classic from the Violet Highlands, the realm of 25 Wizards and endless debate, who found their orange hat not through spectacular trial but through quiet, daily courage. Commonflame was a city scribe who walked the same route to work every day through increasingly dangerous streets during the pre-Loyalty Wars tensions. While nobles hired guards and merchants found new routes, Commonflame simply... kept walking. The hat found them on a Tuesday, manifesting not in dramatic flame but as a warm glow on their head as they helped an injured stranger.\n\nTheir power lies not in extraordinary combat magic but in extraordinary determination. Commonflame's flames never go out, not flashy, but absolutely reliable. They serve as the Flame's ambassador to the Violet Highlands' Grand Assembly, translating between the political language of Classics and the direct language of fire. The hoodie they wear marks them as approachable; they're the Flame Wizard most likely to have a normal conversation about normal things. But when politics threaten to explode into violence, Commonflame's steady flame reminds everyone that true strength doesn't need to shout."},
    {"number": 3758, "name": null, "image": "images/dogs/3758.png", "traits": [["Background", "Pink"], ["Fur Color", "Purple"], ["Fur Pattern", "Zombie"], ["Head", "Wizard"], ["Eyes", "Red"]], "rank": 3040, "title": "Deathbloom the Renewal Bringer", "order": "Wild", "realm": "Shadowmire", "lore": "The most visually striking Wild Wizard, purple fur with red eyes from the realm of decay practicing the magic of growth. Deathbloom represents the Wild's understanding that death and growth are partners, not enemies. Their Zombie heritage means they understand decay from the inside, while their red eyes see the life force that persists even in dying things. The green hat chose them during their first bloom, a moment when their purple fur sprouted actual flowers, proving that even death-touched beings can nurture life.\n\nTheir magic is Necromantic Botany, growing plants from dead soil, using the nutrients in decay to fuel new growth, and creating gardens that flourish in graveyards and battlefields. Deathbloom tends the memorial groves where fallen Wizards are honored, ensuring that death serves life in an endless cycle. Their purple and green color combination creates visual harmony between death and growth, while their red eyes track the life force that flows from ending to beginning."},
    {"number": 8965, "name": null, "image": "images/dogs/8965.png", "traits": [["Background", "Pink"], ["Fur Color", "Brown"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Scarf"], ["Eyes", "Black"]], "rank": 3183, "title": "Brownthorn the Shield Grower", "order": "Wild", "realm": "Violet Highlands", "lore": "A practical Classic from the Violet Highlands who earned their green hat through defensive magic rather than aggressive growth. Brownthorn's brown fur blends perfectly with tree bark and rich soil, while their scarf is woven from thorn-vine fibers that provide natural armor. They found their calling during the Loyalty Wars, when they used rapid-growth magic to create living barriers that protected civilians from combat magic.\n\nTheir specialty is Defensive Botany, walls of thorns that grow in seconds, root networks that detect approaching threats, and tree canopies that provide natural shelter. Brownthorn's magic focuses on protection rather than attack, creating living fortifications that grow stronger with time. They serve as the Wild's defensive specialist, proving that nature magic is most powerful when it preserves rather than destroys. Their Classic steadiness makes them ideal for long-term protective magic that must remain stable for years."},
    {"number": 3030, "name": null, "image": "images/dogs/3030.png", "traits": [["Background", "Tan"], ["Fur Color", "White"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Mouth", "Steak"], ["Eyes", "Black"]], "rank": 3305, "title": "Pureflame the Unadorned", "order": "Flame", "realm": "Violet Highlands", "lore": "The most minimalist Flame Wizard. No accessories, no distinctive clothing, nothing but white fur and black eyes and an orange hat. Pureflame's origin story is almost disappointingly simple: they walked into the Trial by Fire with nothing and emerged with everything. The Flame's magic chose them precisely because they brought no expectations, no baggage, no preconceptions about what fire magic should be.\n\nTheir specialty is Essential Flame, fire stripped of everything except the core concept of transformation. When Pureflame casts, their magic appears as simple orange light, but it cuts through the most complex defensive spells like they're paper. They refuse all ornamentation, all titles beyond their name, all complications that might dilute their focus. Other Flame Wizards joke that Pureflame is so pure they barely cast shadows. They're not wrong. In the philosophical debates that rage within any Order, Pureflame represents the position that fire doesn't need a reason to burn, it burns because burning is what fire does."},
    {"number": 986, "name": null, "image": "images/dogs/986.png", "traits": [["Background", "Pink"], ["Fur Color", "Gray"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Square Glasses"]], "rank": 3638, "title": "Splitforge the Dual Natured", "order": "Flame", "realm": "Abyssal Reaches", "lore": "A Split-furred diplomat from the Abyssal Reaches who found their orange hat in the most unlikely place: the middle of a peace negotiation. Splitforge was mediating a dispute between rival fishing fleets when both sides' anger erupted into violence. Instead of fleeing or choosing sides, they stood between the combatants and spoke, not words of peace, but words of challenge. \"If you must fight,\" they said, \"fight something that fights back.\" The hat manifested as they offered themselves as the target for both fleets' rage.\n\nSplitforge's dual nature makes them unique among the Flame. Their Split fur literally divides their magical expression, one half channels aggressive flame, the other controlled burn. They can simultaneously attack and defend, destroy and preserve. Their square glasses reflect their analytical approach to combat magic. They serve as the Flame's specialist in conflict resolution through controlled escalation, sometimes the best way to prevent a war is to give people a small, safe fight that satisfies their need for violence. Splitforge provides that service, channeling societal anger into manageable fire."},
    {"number": 165, "name": null, "image": "images/dogs/165.png", "traits": [["Background", "Blue"], ["Fur Color", "Gray"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Eyes", "Visor"]], "rank": 3732, "title": "Vanguard the Glacier Walker", "order": "Flame", "realm": "Frosthollow", "lore": "The third Husky in the Flame Order, proving that Frosthollow breeds something special in ice-dogs who choose fire. Vanguard earned their orange hat by doing what no other dog had done: they walked across the Frozen Lake of Echoes during a blizzard, guided only by the visor that protected their eyes from ice-glare. The lake preserves sounds from thousands of years, howls, conversations, the echoes of the First Howl itself. As Vanguard crossed, they listened to every preserved sound and chose the ones worth preserving in flame.\n\nTheir visor isn't just protection; it's a magical focus that lets them see heat signatures through ice, smoke, and flame. Vanguard serves as the Flame's arctic specialist, the only Wizard who can forge weapons in sub-zero temperatures. Their signature creation is Glacier Glass, transparent metal harder than steel, forged from ice and fire in perfect balance. They lead scouting missions into territories too cold for other Flame Wizards, proving that fire doesn't fear cold, it conquers it."},
    {"number": 5275, "name": null, "image": "images/dogs/5275.png", "traits": [["Background", "Red"], ["Fur Color", "Brown"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Yellow"]], "rank": 3857, "title": "Tideforge the Current Rider", "order": "Flame", "realm": "Abyssal Reaches", "lore": "From the coastal cliffs where land meets sea, Tideforge brought the rhythm of waves to the chaos of flame. Their Split nature, half sea-blue, half sun-gold, made them natural mediators in the Abyssal Reaches' constantly shifting politics. The orange hat found them during the Tidal Court sessions, when they alone spoke for both the above-water and below-water factions simultaneously. As they argued two contradictory positions with equal passion, the hat manifested, recognizing that sometimes the greatest courage is being willing to disagree with yourself.\n\nTheir yellow eyes see through water as clearly as air, making them the Flame's naval specialist. Tideforge's fire burns even underwater, fed by the friction between opposing forces rather than by air. They serve as liaison to the Abyssal Reaches' government, translating between the Split realm's dual-perspective politics and the Flame's direct action philosophy. When the Forge Spire needs weapons that function in all environments, Tideforge creates fire that adapts to its surroundings like a tide."},
    {"number": 3557, "name": null, "image": "images/dogs/3557.png", "traits": [["Background", "Rose"], ["Fur Color", "Yellow"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Yellow"]], "rank": 3868, "title": "Goldstare the Solar Prophet", "order": "Deep", "realm": "Ember Wastes", "lore": "A Tiger from the volcanic Ember Wastes whose perfect yellow-on-yellow coloring creates unique resonance with light-based prophecy. Goldstare's solitary hunting instincts evolved into patient observation of probability patterns, while their yellow eyes see not just heat signatures but the thermal patterns of possible futures. They earned their blue hat during a volcanic eruption, when they successfully predicted the exact path of lava flows by reading the heat signatures of probability itself.\n\nTheir specialty is Solar Scrying, using concentrated sunlight as a medium for prophecy, reading futures in the patterns of light and shadow, and predicting events that will occur during daylight hours. Goldstare's Tiger nature makes them most powerful when working alone, avoiding the interference that group scrying sessions create. They serve as the Deep's daytime prophet, complementing colleagues who work better in darkness or underwater environments. Their perfect yellow coloring means they literally glow when channeling solar prophecy, becoming briefly too bright to look at directly."},
    {"number": 9025, "name": null, "image": "images/dogs/9025.png", "traits": [["Background", "Yellow"], ["Fur Color", "Gray"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Red"]], "rank": 3879, "title": "Grayheart the Split Revealer", "order": "Radiant", "realm": "Abyssal Reaches", "lore": "From the realm of duality and complex perspectives, Grayheart brings Split vision to revelation magic. Their gray base color with subtle split-toning provides perfect neutrality for truth-magic, while their red eyes see oneiroic truth as clearly as factual truth. They specialize in Diplomatic Revelation, showing people uncomfortable truths in ways that promote understanding rather than conflict.\n\nTheir magic focuses on Balanced Truth, revealing both sides of complex situations, showing how apparent contradictions can both be true, and using light magic to illuminate the common ground hidden beneath surface disagreements. Grayheart's Split nature lets them understand multiple perspectives simultaneously, while their red eyes track the oneiroic dynamics that determine whether revealed truth will be accepted or rejected. They serve as the Radiant's specialist in conflict resolution through enlightenment."},
    {"number": 8311, "name": null, "image": "images/dogs/8311.png", "traits": [["Background", "Purple"], ["Fur Color", "Yellow"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Visor"]], "rank": 3893, "title": "Goldvisor the Tiger Theorist", "order": "Dream", "realm": "Ember Wastes", "lore": "The second Tiger in the Dream Order, bringing analytical rigor to the intuitive art of dream magic. Goldvisor develops the theoretical frameworks that make oneiroic amplification predictable and reliable. Their yellow fur resonates with light-based magic, while their visor protects against the disorienting effects of working with multiple theoretical frameworks simultaneously. They earned recognition by developing the mathematical models that predict when temporal magic will succeed or cause paradoxes.\n\nTheir magic is Theoretical Dream, creating the underlying principles that guide practical applications of dream magic. Goldvisor writes the textbooks that other Dream Wizards study, developing dream-boundary safeguards in collaboration with Arcane dimensional theorists. Their Tiger instincts for patient stalking translate into methodical pursuit of theoretical breakthroughs that might take years to complete. The visor they wear displays magical equations and theoretical frameworks directly onto their field of vision."},
    {"number": 6873, "name": null, "image": "images/dogs/6873.png", "traits": [["Background", "Green"], ["Fur Color", "Yellow"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Mixed"]], "rank": 3935, "title": "Goldleaf the Multi Eyed", "order": "Wild", "realm": "Sunward Heights", "lore": "The only Wild Wizard with mixed-color eyes, creating a connection to multiple magical frequencies simultaneously. Goldleaf's yellow Solid fur creates perfect resonance with sunlight, while their mixed eyes let them see both solar energy and earth energy as interconnected systems. They earned their green hat by creating the first plants that could photosynthesize moonlight as efficiently as sunlight, extending growing seasons into the night.\n\nTheir magic specializes in Solar Botany, plants that store sunlight like batteries, releasing it gradually to power growth during cloudy periods. Goldleaf's yellow fur actually photosynthesizes, making them partially plant themselves. They serve as the Wild's connection to solar energy cycles, ensuring that forest magic remains strong even during the winter months when daylight is scarce; their magic remains tied to Evergreen, not Solaris. Their mixed eyes see the color spectrum differently each day, allowing them to tune plant growth to specific wavelengths of light."},
    {"number": 9301, "name": null, "image": "images/dogs/9301.png", "traits": [["Background", "Red"], ["Fur Color", "Yellow"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Pink"]], "rank": 3938, "title": "Rosegold the Pink Eyed Theorist", "order": "Dream", "realm": "Sunward Heights", "lore": "One of two Solids in the Dream Order; Lensheart studies Analytical Empathy, while Rosegold explores emotional color. Their pink eyes see the subconscious components of magical energy, while their yellow Solid fur provides the clarity needed to analyze complex dream patterns without being overwhelmed by them. They developed the theoretical framework for understanding how oneiroic energy affects magical efficiency.\n\nTheir specialty is Emotional Dream Magic, understanding how feelings influence magical outcomes, predicting which subconscious currents will enhance or interfere with specific spells, and developing techniques for dream-state regulation during complex magical work. Rosegold's research explains why some magical partnerships work perfectly while others fail catastrophically. They serve as the Dream's specialist in group bond theory, developing the protocols that allow multiple Dream Wizards to work together without their individual magical styles interfering with each other."},
    {"number": 8667, "name": null, "image": "images/dogs/8667.png", "traits": [["Background", "Purple"], ["Fur Color", "Orange"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Sleepy"]], "rank": 3969, "title": "Goldforge the Sun Touched", "order": "Flame", "realm": "Sunward Heights", "lore": "The only orange-furred Flame Wizard, creating a perfect visual harmony between breed and Order. From the sun-drenched Sunward Heights, where everything is pure and bright, Goldforge seemed destined for the Radiant Order's light magic. But when the Sorting Ceremony came, it was an orange hat that chose them, not because they radiated light, but because they absorbed it. Their sleepy eyes hide an inner furnace that burns on stored solar energy, making them most powerful at noon and during solar storms.\n\nGoldforge represents the Flame's connection to stellar fire rather than earthly flame. Their magic draws directly from the sun, creating weapons that blaze with daylight intensity. They are the only Flame Wizard whose magic gets stronger in bright light rather than weaker. During the summer solstice, when Solaris peaks, Goldforge's power rivals any Radiant Wizard's. Their sleepy demeanor masks the fact that they're constantly processing enormous amounts of solar energy. When they fully wake up, the results can be seen from orbit."},
    {"number": 7770, "name": null, "image": "images/dogs/7770.png", "traits": [["Background", "Purple"], ["Fur Color", "Gray"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Red"]], "rank": 3986, "title": "Stripesight the Pattern Burner", "order": "Flame", "realm": "Ember Wastes", "lore": "A Tiger from the volcanic Ember Wastes, where Tigers naturally thrive, but unique even among their stripe-patterned kin. Stripesight's red eyes, an uncommon eye color among Wizards, see not just heat but the patterns within fire. When other Tigers practice solitary ambush magic, Stripesight studied the mathematical beauty of flame spread, the fractal patterns of ember trails, the hidden geometry of explosion. Their orange hat appeared during the Ash Garden burns, manifesting as they traced flame patterns in volcanic ash.\n\nTheir Tiger stripes store magical energy in complex patterns, releasing it in controlled burns that follow precise mathematical sequences. Stripesight creates fire that burns in fractals, flames that follow geometric progression, controlled explosions that bloom in perfect spirals. They serve as the Flame's master of precision destruction, when the Order needs to burn exactly this much and no more, Stripesight calculates the pattern. Their red eyes reflect not anger but the deep satisfaction of an artist whose medium happens to be fire."},
    {"number": 2807, "name": null, "image": "images/dogs/2807.png", "traits": [["Background", "Tan"], ["Fur Color", "Green"], ["Fur Pattern", "Zombie"], ["Head", "Wizard"], ["Eyes", "Visor"]], "rank": 4035, "title": "Voidbloom the Visor Wearer", "order": "Wild", "realm": "Shadowmire", "lore": "The second Zombie in the Wild Order, but where Deathbloom works with death-to-life transitions, Voidbloom specializes in void-to-growth magic. Their green fur matches their Order's color perfectly, while the visor they wear protects against the disorientation of seeing plants grow in magical darkness. Voidbloom earned their place by growing the first garden in the Shadowmire's dark valleys, where normal photosynthesis is impossible.\n\nTheir magic is Void Botany, plants that grow without sunlight, drawing energy from magical darkness and shadow. These shadow plants serve as food sources in underground areas and during eclipse periods when normal agriculture fails. Voidbloom's visor contains crystallized darkness that lets them see how shadow interacts with living things. They prove that growth is possible anywhere life is needed, regardless of environmental conditions."},
    {"number": 5056, "name": null, "image": "images/dogs/5056.png", "traits": [["Background", "Purple"], ["Fur Color", "Brown"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Visor"]], "rank": 4059, "title": "Brownvisor the Research Director", "order": "Arcane", "realm": "Ember Wastes", "lore": "One of two Tigers in the Arcane Order, joining the scholars who bring predatory focus to academic research. Brownvisor's brown fur provides perfect camouflage in library settings, while their visor displays research notes and magical formulas directly in their field of vision. They serve as the research coordinator for the most dangerous magical experiments, ensuring that Tiger reflexes protect researchers when theory meets practice.\n\nTheir magic is Experimental Arcane, testing new magical theories under controlled conditions, developing safety protocols for dangerous research, and coordinating between theoretical development and practical application. Brownvisor's Tiger instincts make them perfect for anticipating when magical experiments are about to go wrong, while their scholarly training provides the knowledge needed to prevent catastrophic failures. They maintain the Violet Citadel's restricted laboratories where the most dangerous magical research takes place."},
    {"number": 7710, "name": null, "image": "images/dogs/7710.png", "traits": [["Background", "Rose"], ["Fur Color", "Yellow"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Sleepy"]], "rank": 4081, "title": "Goldstrike the Lightning Fast", "order": "Flame", "realm": "Sunward Heights", "lore": "Another Solid from the Sunward Heights, but where Goldforge burns steady and bright, Goldstrike burns in rapid bursts. Their yellow fur gleams like captured lightning, and despite their sleepy appearance, they are the fastest draw in the Flame Order. The orange hat found them during a moment of perfect reaction time, a rockslide threatening a trading caravan, Goldstrike moving without thought to create a controlled explosion that redirected the falling stones.\n\nTheir magic manifests as Lightning Fire, flame that moves at the speed of electricity, strikes with surgical precision, and dissipates immediately. Perfect for rescue operations where sustained heat would cause more damage than the original problem. Goldstrike's sleepy eyes are actually constantly calculating trajectory, timing, and force needed for split-second interventions. They serve as the Flame's rapid response specialist, arriving at emergencies before the call for help finishes echoing through the Loyalty Network."},
    {"number": 9952, "name": null, "image": "images/dogs/9952.png", "traits": [["Background", "Green"], ["Fur Color", "Black"], ["Fur Pattern", "Zombie"], ["Head", "Wizard"], ["Eyes", "Green"]], "rank": 4082, "title": "Grimbloom the Green Eyed", "order": "Wild", "realm": "Shadowmire", "lore": "The darkest Wild Wizard, their black Zombie fur creating stark contrast with green Order magic. Grimbloom's green eyes see life force directly, making them capable of detecting the faintest spark of vitality in seemingly dead environments. They specialize in resurrection botany, bringing dead plants back to life, not as undead vegetation but as renewed living things.\n\nTheir magic focuses on Second Chance Growth, giving failed crops another opportunity to thrive, reviving forests damaged by magical combat, and maintaining the Shadowmire's ecosystem despite constant decay and transformation. Grimbloom's black fur makes them invisible in the deepest forest shadows, while their green eyes serve as beacons for lost creatures seeking the safety of growing things. They represent the Wild's commitment to giving every living thing multiple opportunities to survive and thrive."},
    {"number": 1848, "name": null, "image": "images/dogs/1848.png", "traits": [["Background", "Green"], ["Fur Color", "Yellow"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Round Glasses"]], "rank": 4120, "title": "Lensfire the Tiger Scholar", "order": "Flame", "realm": "Ember Wastes", "lore": "The most academic Tiger in the Ember Wastes, and possibly the only Tiger who reads for pleasure. Lensfire's round glasses mark them as scholarly in a realm that values instinct over study, independence over collaboration. But when their orange hat manifested, it wasn't during solo meditation but during the most collaborative moment of their life, teaching young Tigers how to control their stripe-stored magic. The hat recognized that sometimes the greatest courage is admitting you don't know everything.\n\nTheir glasses focus more than just vision; they focus flame into precise tools for magical research. Lensfire burns away ignorance the way others burn away enemies, using fire to reveal hidden truths by destroying everything that obscures them. They serve as the Flame's research director, conducting experiments too dangerous for anyone without Tiger reflexes and scholarly patience. When the Order encounters unknown magic, Lensfire burns controlled samples until they understand how it works."},
    {"number": 5240, "name": null, "image": "images/dogs/5240.png", "traits": [["Background", "Purple"], ["Fur Color", "Gray"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Sleepy"]], "rank": 4173, "title": "Graysleep the Dream Walker", "order": "Arcane", "realm": "Sunward Heights", "lore": "The third Solid from the Sunward Heights, but unlike their bright-colored colleagues, Graysleep specializes in magic that works during sleep and unconsciousness. Their gray fur provides neutrality that doesn't interfere with dream magic, while their permanently sleepy appearance reflects their specialty in unconscious mental states. They earned their purple hat by successfully entering and mapping the collective unconscious of an entire realm.\n\nTheir magic is Dream Arcane, working with sleeping minds, accessing memories that are only available during unconsciousness, and using dream logic to solve problems that defeat waking analysis. Graysleep spends most of their time asleep, conducting magical research in dream states where normal physical limitations don't apply. They serve as the Arcane's specialist in sleep magic and unconscious mental processes, proving that some forms of knowledge can only be accessed when the conscious mind steps aside."},
    {"number": 2634, "name": null, "image": "images/dogs/2634.png", "traits": [["Background", "Aqua"], ["Fur Color", "Black"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Mixed"]], "rank": 4331, "title": "Mixedsight the Paradox Prophet", "order": "Deep", "realm": "Abyssal Reaches", "lore": "From the realm of duality and impossible perspectives, Mixedsight brings Split double-vision to prophecy magic. Their black Split fur creates perfect contrast patterns, while their mixed-color eyes see different aspects of the same future simultaneously. One eye sees what will happen if current trends continue; the other sees what will happen if key variables change. They earned their blue hat by successfully predicting both outcomes of a major political crisis, then watching both futures occur simultaneously in parallel timeline streams.\n\nTheir specialty is Paradox Prophecy, seeing futures that contradict each other but are somehow both true, predicting the unpredictable moments when reality splits into multiple valid possibilities, and navigating the temporal confusion that results when multiple timelines converge. Mixedsight's Split nature lets them experience contradictory visions without mental strain, while their mixed eyes track multiple probability streams simultaneously. They serve as the Deep's specialist in crisis prophecy, predicting the moments when normal cause-and-effect breaks down and multiple futures become possible."},
    {"number": 4540, "name": null, "image": "images/dogs/4540.png", "traits": [["Background", "Blue"], ["Fur Color", "White"], ["Fur Pattern", "Blotted"], ["Head", "Wizard"], ["Eyes", "Visor"]], "rank": 4490, "title": "Blotforge the Chaos Shaper", "order": "Flame", "realm": "Shadowmire", "lore": "A Shadowmire representative in the Flame Order, carrying the prejudices of both their dark homeland and their fire-bright Order. Blotforge's blotted pattern, irregular, asymmetric, chaotic, makes them an outcast in an Order that values controlled power and disciplined technique. But their white base color reflects all light, making their unpredictable blots into a strength rather than a weakness. The orange hat found them in the Shifting Grounds during a territory rearrangement, when they alone remained standing as the earth literally reformed around them.\n\nTheir visor protects against the chaos of their own magic as much as external threats. Blotforge's flame follows no pattern because pattern is limitation, their fire adapts, mutates, and evolves in real time to overcome any obstacle. They represent the Flame's answer to enemies who adapt to conventional fire magic: unpredictable flame that cannot be predicted or countered. Other Flame Wizards create controlled burns. Blotforge creates intelligent burns that learn from resistance."},
    {"number": 8095, "name": null, "image": "images/dogs/8095.png", "traits": [["Background", "Tan"], ["Fur Color", "Gray"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Pink"]], "rank": 4524, "title": "Rosestrike the Pink Eyed", "order": "Flame", "realm": "Abyssal Reaches", "lore": "From the tidal politics of the Abyssal Reaches, where every decision requires balancing two perspectives, Rosestrike brought the rare gift of pink eyes, eyes that see oneiroic energy as clearly as physical matter. In their homeland's Twin Council system, they served as the oneiroic interpreter, helping negotiators understand not just what was said but what was felt. The orange hat manifested during a particularly heated debate when they stood up and declared, \"Stop arguing about positions. Fight for principles.\"\n\nTheir pink eyes let them see the oneiroic fuel behind magical energy, making them uniquely suited to combat magic that draws on passion rather than technique. Rosestrike's flames burn brightest when fighting for something rather than against something, making them the Flame's specialist in defensive combat and protection magic. They can literally see love, honor, loyalty, and courage as flames that can be amplified and weaponized. When Rosestrike fights, they're not just wielding fire, they're wielding the oneiroic energy that makes fire worth using."},
    {"number": 4994, "name": null, "image": "images/dogs/4994.png", "traits": [["Background", "Red"], ["Fur Color", "White"], ["Fur Pattern", "Collie"], ["Head", "Wizard"], ["Eyes", "Red"]], "rank": 4600, "title": "Whitecoat the Collie Coordinator", "order": "Arcane", "realm": "Deepwood", "lore": "One of two Collies in the Arcane Order, bringing herding instincts to the challenge of organizing magical knowledge. Whitecoat's white fur and red eyes create striking visual contrast, while their Collie breeding provides the coordination skills needed to keep track of multiple complex research projects simultaneously. They earned recognition by successfully organizing the Violet Citadel's entire library system, ensuring that no knowledge is ever truly lost.\n\nTheir specialty is Information Herding, keeping track of how different pieces of knowledge relate to each other, ensuring that research findings are shared between appropriate parties, and preventing important discoveries from getting lost in the archives. Whitecoat treats knowledge like a flock that needs constant attention to prevent straying. Their red eyes track information pathways the way other Collies track animal movements, ensuring that the right knowledge reaches the right researcher at the right time."},
    {"number": 8342, "name": null, "image": "images/dogs/8342.png", "traits": [["Background", "Green"], ["Fur Color", "White"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Red"]], "rank": 4624, "title": "Whiteheart the Split Researcher", "order": "Dream", "realm": "Abyssal Reaches", "lore": "From the realm of duality and diplomatic complexity, Whiteheart brings Split perspectives to dream-thread magic. Their white base color with subtle dual-toning reflects their ability to see both sides of theoretical debates, while their red eyes provide the subconscious insight needed to understand why different researchers reach different conclusions from the same evidence. They specialize in research that requires considering multiple incompatible theories simultaneously.\n\nTheir magic is Paradox Dream, working with magical theories that seem to contradict each other but are somehow both true. Whiteheart's Split nature lets them hold opposing ideas in their mind without resolving the contradiction, which is essential for understanding magic that operates according to paradoxical principles. They serve as the Dream's specialist in paradoxical bonds that have no single correct answer, developing magical techniques that work precisely because they shouldn't work."},
    {"number": 8284, "name": null, "image": "images/dogs/8284.png", "traits": [["Background", "Purple"], ["Fur Color", "Black"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Round Glasses"]], "rank": 4766, "title": "Stripesight the Pattern Hunter", "order": "Wild", "realm": "Ember Wastes", "lore": "A black Tiger from the Ember Wastes whose solitary hunting instincts evolved into pattern-tracking abilities that serve the collective needs of forest ecosystems. Stripesight's black fur with faint stripe patterns creates perfect camouflage in burnt forest areas, while their round glasses help them see growth patterns in areas damaged by volcanic activity. They earned their green hat by tracking and cataloging every surviving seed in post-eruption wastelands.\n\nTheir specialty is Recovery Botany, identifying which plants will grow back naturally after disasters and which need magical assistance. Stripesight hunts not animals but opportunities for growth, stalking through damaged landscapes to find the hidden potential for renewal. Their Tiger instincts make them expert at finding the one perfect seed that can restart an entire ecosystem. They serve as the Wild's disaster response specialist, arriving at natural catastrophes to begin immediate restoration efforts."},
    {"number": 6203, "name": null, "image": "images/dogs/6203.png", "traits": [["Background", "Tan"], ["Fur Color", "Tan"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Eyes", "Sleepy"]], "rank": 4781, "title": "Sleepytan the Dream Revealer", "order": "Radiant", "realm": "Frosthollow", "lore": "The second Husky in the Radiant Order, but where Tancollar focuses on arctic light-magic, Sleepytan specializes in revelation that occurs during rest and unconsciousness. Their tan fur provides earth-tone stability for dream-work, while their permanently sleepy appearance reflects their specialty in unconscious truth-revelation.\n\nTheir magic is Sleep Revelation, showing people important truths through prophetic dreams, cleansing false beliefs while the subject sleeps, and providing gentle enlightenment that doesn't disturb daily life. Sleepytan's Husky endurance makes them ideal for maintaining dream-magic over extended periods, while their sleepy nature allows them to work in unconscious states where revelation is less traumatic. They serve as the Radiant's dream specialist, providing truth-magic that works through rest rather than confrontation."},
    {"number": 9826, "name": null, "image": "images/dogs/9826.png", "traits": [["Background", "Purple"], ["Fur Color", "Green"], ["Fur Pattern", "Zombie"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 4845, "title": "Greenbone the Chaos Scholar", "order": "Dream", "realm": "Shadowmire", "lore": "The only Shadowmire representative in the Dream Order, bringing chaos magic principles to dream-thread work. Greenbone's green Zombie fur creates a living connection to decay and transformation processes, while their black eyes see the order hidden within apparent chaos. They earned their magenta hat by successfully cataloguing and organizing the Shadowmire's shapeshifting terrain, creating maps of a landscape that changes faster than maps can be drawn.\n\nTheir specialty is Chaos Dream Theory, finding the hidden patterns in random events, predicting probable outcomes from chaotic systems, and developing magical techniques that harness randomness for controlled results. Greenbone's Zombie nature means they understand transformation from the inside, while their scholarly training provides the analytical tools needed to make chaos comprehensible. They serve as the Dream's specialist in unpredictable bonds and chaos-based oneiroic systems."},
    {"number": 4742, "name": null, "image": "images/dogs/4742.png", "traits": [["Background", "Yellow"], ["Fur Color", "White"], ["Fur Pattern", "Blotted"], ["Head", "Wizard"], ["Eyes", "Sleepy"]], "rank": 5050, "title": "Blottedmist the Chaos Seer", "order": "Deep", "realm": "Shadowmire", "lore": "From the ever-changing Shadowmire, Blottedmist brings chaos magic principles to prophecy work. Their white base color with irregular blotting provides perfect camouflage in situations where normal pattern-recognition fails, while their sleepy eyes mask intense concentration on probability patterns that shift too rapidly for normal observation. They earned recognition by successfully predicting events in the Shadowmire's shapeshifting terrain, where normal prophecy magic fails because the landscape changes faster than visions can form.\n\nTheir magic is Chaos Prophecy, predicting the unpredictable, finding pattern in randomness, and reading futures in systems too complex for conventional analysis. Blottedmist's blotted pattern changes to reflect the probability patterns they're currently tracking, creating a living map of chaos magic systems. Their sleepy appearance masks hyperactive mental processes that must track thousands of shifting variables simultaneously. They serve as the Deep's specialist in impossible predictions, seeing futures that shouldn't be possible but somehow occur anyway."},
    {"number": 6095, "name": null, "image": "images/dogs/6095.png", "traits": [["Background", "Yellow"], ["Fur Color", "White"], ["Fur Pattern", "Dalmatian"], ["Head", "Wizard"], ["Eyes", "Square Glasses"]], "rank": 5093, "title": "Dalmatianscript the Unique Scholar", "order": "Arcane", "realm": "Deepwood", "lore": "The collection's only Dalmatian Wizard, making them as unique among the 86 as their breed is among all dogs. Dalmatianscript's white coat with perfectly placed spots creates a living text where each spot represents a different piece of magical knowledge. Their square glasses focus not just vision but magical perception, allowing them to read the hidden texts that appear on surfaces throughout the Violet Citadel when illuminated by Umbra's light.\n\nTheir specialty is Textual Arcane, magic that works through written symbols, spells that are cast by writing rather than speaking, and the preservation of knowledge in forms that can survive any catastrophe. Each spot on their coat contains a different spell or piece of information, creating a living spellbook that can never be lost or destroyed. They serve as the Arcane's ultimate backup system, carrying the Order's most essential knowledge literally in their skin. Their unique breed status makes them a living reminder that knowledge takes many forms, some of which appear only once in history."},
    {"number": 5518, "name": null, "image": "images/dogs/5518.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Green"]], "rank": 5144, "title": "Voidstrike the Green Eyed", "order": "Flame", "realm": "Abyssal Reaches", "lore": "The darkest-furred Flame Wizard, their black Split pattern creating a visual contradiction with orange flame that somehow works perfectly. Voidstrike's green eyes, unusual for any breed, see magical voids, the empty spaces where magic should be but isn't. They found their calling during the Great Silence's aftermath, identifying and mapping the \"dead bonds\" left in the Loyalty Network by the magical shutdown. The orange hat appeared as they worked to reforge broken magical connections through controlled flame.\n\nTheir specialty is Void Fire, flame that burns in magical darkness, drawing fuel from the absence of other magic rather than its presence. When enemies create magical barriers or null-magic zones, Voidstrike's fire burns brighter. They serve as the Flame's specialist in anti-magic combat, creating fire that consumes magical defenses the way normal fire consumes wood. Their black fur makes them nearly invisible in smoke and shadow, while their green eyes track magical signatures others can't detect."},
    {"number": 5374, "name": null, "image": "images/dogs/5374.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Spotted"], ["Head", "Wizard"], ["Eyes", "Red"]], "rank": 5224, "title": "Redsight the Spotted Tracker", "order": "Wild", "realm": "Deepwood", "lore": "A native Deepwood Wizard whose black coat with spots creates living camouflage that changes pattern based on surroundings. Redsight's red eyes, the rarest eye color, see heat signatures and life force simultaneously, making them the Wild's most effective tracker of both healthy and diseased plant life. They earned recognition by being the first to identify the Great Rot's early symptoms, tracking the corruption's spread through forest networks before it became visible to normal sight.\n\nTheir magic is Diagnostic Botany, identifying plant diseases, tracking the health of forest networks, and prescribing natural remedies for ecosystem problems. Redsight's spotted pattern acts as a living health map, with each spot corresponding to a different area of forest and changing color to reflect its condition. They serve as the Wild's medical specialist, making house calls to sick trees and prescribing growth treatments for damaged ecosystems."},
    {"number": 3826, "name": null, "image": "images/dogs/3826.png", "traits": [["Background", "Pink"], ["Fur Color", "Orange"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Green"]], "rank": 5283, "title": "Rosefield the Wild Ember", "order": "Wild", "realm": "Violet Highlands", "lore": "The only orange-furred Wild Wizard, creating a visual connection between Wild green magic and Flame orange energy. Orangeheart's green eyes provide perfect color balance, while their Classic breeding brings Violet Highlands scholarship to nature magic. They specialize in Fire-Growth Symbiosis, understanding how forest fires create conditions for new growth, and managing controlled burns that rejuvenate ecosystems without causing lasting damage.\n\nTheir orange fur reflects and focuses flame energy, making them immune to natural fire while their green Order magic guides post-fire regeneration. Orangeheart serves as liaison between the Wild and Flame Orders, coordinating between destruction magic and growth magic to create planned renewal cycles. They prove that orange and green can work together when both serve the greater goal of healthy ecosystems."},
    {"number": 9898, "name": null, "image": "images/dogs/9898.png", "traits": [["Background", "Green"], ["Fur Color", "Orange"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Green"]], "rank": 5299, "title": "Verdant the Arcane Flame", "order": "Arcane", "realm": "Violet Highlands", "lore": "An unusual color combination, orange Classic fur with green eyes, creating visual connections to multiple Orders simultaneously. Orangeheart serves as the Arcane's liaison to other Orders, using their orange fur to connect with Flame discipline and their green eyes to understand Wild magic theory. Their Classic breeding provides the diplomatic stability needed to translate between different magical philosophies without losing essential meaning.\n\nTheir magic is Translation Arcane, converting magical techniques from one discipline to another, finding the common theoretical foundations that underlie different Orders' approaches to magic, and developing hybrid techniques that combine multiple disciplines. Orangeheart's unusual coloring reflects their role as a bridge between different magical traditions. They serve as proof that Arcane magic works best when it integrates knowledge from all sources rather than pursuing isolated theoretical development."},
    {"number": 6135, "name": null, "image": "images/dogs/6135.png", "traits": [["Background", "Red"], ["Fur Color", "Blue"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Visor"]], "rank": 5309, "title": "Bluevisor the Technology Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "The only blue-furred Deep Wizard, creating perfect color resonance between their coat and their Order's discipline. Bluevisor's visor displays not just current information but probability projections and timeline analysis, turning their field of vision into a real-time prophecy interface. They earned their position by developing new techniques for technological prophecy, predicting not just what will happen, but what inventions and magical developments will make it possible.\n\nTheir specialty is Innovation Prophecy, seeing the future discoveries that will change how magic works, predicting which experimental technologies will succeed, and preparing for the social changes that new magical capabilities will create. Bluevisor's Classic stability provides the mental framework needed to process rapidly changing technological possibilities without being overwhelmed by infinite potential. They serve as the Deep's technology advisor, ensuring that the Order stays ahead of magical developments that might affect prophecy accuracy."},
    {"number": 8154, "name": null, "image": "images/dogs/8154.png", "traits": [["Background", "Purple"], ["Fur Color", "Gray"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Square Glasses"]], "rank": 5549, "title": "Grayveil the Foundation Scholar", "order": "Arcane", "realm": "Violet Highlands", "lore": "The most typical-looking Arcane Wizard, gray Classic fur, square glasses, nothing flashy or distinctive. But Grayglasses represents the foundation of all Arcane magic: patient, methodical, thorough research into basic principles that support more advanced magical development. Their gray coloring provides perfect neutrality for magical experiments, while their square glasses focus their attention on precise details that more dramatic researchers might overlook.\n\nTheir magic is Foundation Arcane, establishing the basic principles that allow advanced magic to work, maintaining the ward systems that protect the Violet Citadel, and ensuring that experimental magic doesn't destabilize the fundamental forces that keep reality consistent. Grayglasses performs the unglamorous but essential work that makes spectacular magical achievements possible. They serve as the Arcane's most reliable researcher, producing steady progress on long-term projects that require decades of consistent effort."},
    {"number": 1714, "name": null, "image": "images/dogs/1714.png", "traits": [["Background", "Pink"], ["Fur Color", "Brown"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Pink"]], "rank": 5584, "title": "Roseheart the Gentle Flame", "order": "Flame", "realm": "Violet Highlands", "lore": "The most diplomatic Flame Wizard, proving that fire magic doesn't require an aggressive personality. Roseheart's pink eyes and gentle demeanor make them seem more suited to the Dream Order than the Flame, but their orange hat chose them precisely because they understand that the hottest flame is controlled flame. They found their calling during post-Loyalty Wars reconstruction, using precisely controlled fire to clear debris without damaging anything salvageable.\n\nTheir Brown Classic fur marks them as steady and reliable, while their pink eyes let them see the oneiroic damage that combat leaves behind. Roseheart's flames never cause unnecessary harm, they burn away what needs burning and preserve what needs preserving. They serve as the Flame's humanitarian specialist, using fire magic for rescue operations, medical cauterization, and controlled demolition. When other Flame Wizards are too dangerous for civilian work, Roseheart provides fire with a conscience."},
    {"number": 9183, "name": null, "image": "images/dogs/9183.png", "traits": [["Background", "Tan"], ["Fur Color", "White"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Pink"]], "rank": 5726, "title": "Whiteheart the Pink Eyed Illuminator", "order": "Radiant", "realm": "Abyssal Reaches", "lore": "A Split from the diplomatic Abyssal Reaches whose white fur and pink eyes create perfect harmony for compassionate revelation magic. Whiteheart's white base color reflects all forms of light without absorption, while their pink eyes see the oneiroic impact of revealed truth. They specialize in Truth with Mercy, showing people difficult truths in ways that encourage growth rather than despair.\n\nTheir magic is Compassionate Radiance, light that reveals truth gradually, purification that heals rather than burns, and illumination that shows both problems and solutions simultaneously. Whiteheart's Split nature helps them balance truth-telling with kindness, while their pink eyes ensure that their revelations serve healing rather than judgment. They serve as the Radiant's specialist in therapeutic truth-magic for individuals dealing with personal crises."},
    {"number": 7439, "name": null, "image": "images/dogs/7439.png", "traits": [["Background", "Pink"], ["Fur Color", "Yellow"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 5732, "title": "Goldsentry the Gentle Endurer", "order": "Arcane", "realm": "Sunward Heights", "lore": "Goldsentry stands on the ramparts of the Sunward Heights like a living statue , their yellow Solid coat blazing in the perpetual golden light, black eyes scanning horizons that other wizards have long stopped watching. The Arcane Order's most patient guardian, Goldsentry endures. Not with dramatic sacrifice or heroic suffering, but with the quiet, immovable persistence of stone. They guard the old wards, maintain the forgotten barriers, and watch the boundaries that everyone else assumes are safe. Goldsentry knows better. The gentle ones always do."},
    {"number": 4458, "name": null, "image": "images/dogs/4458.png", "traits": [["Background", "Tan"], ["Fur Color", "White"], ["Fur Pattern", "Split"], ["Head", "Wizard"], ["Eyes", "Square Glasses"]], "rank": 5746, "title": "Clearsight the Precision Revealer", "order": "Radiant", "realm": "Abyssal Reaches", "lore": "The second white Split in the Radiant Order, but where Whiteheart focuses on oneiroic aspects of revelation, Whiteglasses specializes in precise, detailed truth-magic. Their square glasses focus light magic into exact measurements and specific details rather than broad illumination. They earned recognition by developing techniques for Forensic Radiance, using light magic to reveal exactly what happened in complex situations.\n\nTheir magic is Precision Truth, illuminating specific facts rather than general truths, revealing exact details that solve mysteries, and providing the focused light needed for detailed investigation work. Whiteglasses serves as the Radiant's specialist in investigative magic, using light to reveal evidence that conventional investigation methods miss. Their Split nature helps them see all sides of complex situations, while their glasses ensure that no important detail is overlooked."},
    {"number": 5177, "name": null, "image": "images/dogs/5177.png", "traits": [["Background", "Red"], ["Fur Color", "Gray"], ["Fur Pattern", "Husky"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 5878, "title": "Frostgrow the Gray Endurer", "order": "Wild", "realm": "Frosthollow", "lore": "The second Husky in the Wild Order, but where Frostbark specializes in cold-weather plants, Frostgrow focuses on plants that bridge seasonal transitions. Their gray fur provides perfect camouflage during the brief Frosthollow summers when snow melts to reveal the brown earth beneath. They earned their green hat by creating the migration gardens, rest stops with magical food sources that sustain animals during long journeys between breeding and wintering grounds.\n\nTheir magic is Transition Botany, plants that change their properties with the seasons, roots that remain active under ice, and seed dispersal systems that work in arctic conditions. Frostgrow maintains the green corridors that connect Frosthollow to other realms, ensuring that migrating creatures have food and shelter during the most vulnerable portions of their journeys. Their Husky endurance makes them ideal for the patient, long-term magic required to establish sustainable ecosystems in harsh climates."},
    {"number": 246, "name": null, "image": "images/dogs/246.png", "traits": [["Background", "Red"], ["Fur Color", "Orange"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 5884, "title": "Goldburn the Solar Flame", "order": "Flame", "realm": "Sunward Heights", "lore": "The second orange-furred Flame Wizard, but where Goldforge channels stored solar energy, Goldburn channels direct solar flame. Their orange Solid coat creates perfect resonance with orange hat magic, making them a walking embodiment of pure Flame discipline. The hat found them during high noon on the summer solstice, as they stood unprotected on the Purified Plateau, deliberately absorbing as much solar energy as their body could hold.\n\nTheir black eyes create stark contrast with orange fur, marking them as a being of absolute focus within absolute power. Goldburn's magic doesn't just use fire, it IS fire, in the purest possible form. They serve as the Flame's connection to stellar forces, the living proof that Order magic can achieve perfect harmony with natural forces. During solar storms, Goldburn becomes temporarily more powerful than any other Flame Wizard. Their presence alone raises the temperature in any room they enter."},
    {"number": 2855, "name": null, "image": "images/dogs/2855.png", "traits": [["Background", "Pink"], ["Fur Color", "Brown"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 5958, "title": "Lensheart the Scholarly Amplifier", "order": "Dream", "realm": "Sunward Heights", "lore": "Lensheart brings scholarly analysis to the intuitive magic of dream-threads. A Brown Solid from the Sunward Heights, they study the mathematical patterns beneath empathy with attentive black eyes. Their name describes an analytical perspective, not physical glasses. They wear no collar or clothing; their magenta hat is their lunar channel.\n\nTheir specialty, Analytical Empathy, studies why bonds form and how they strengthen or weaken. Lensheart works with willing packs to understand shared dreams without reducing individual feelings to equations. Their scholarly method brings rigor to a discipline often guided by intuition. They serve as a Dream theorist, not an Arcane Wizard."},
    {"number": 5516, "name": null, "image": "images/dogs/5516.png", "traits": [["Background", "Tan"], ["Fur Color", "White"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Clothes", "Collar"], ["Eyes", "Black"]], "rank": 5977, "title": "Whiteguard the Shield Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "A defensive specialist whose white fur reflects magical attacks while their black eyes see the aggressive intentions behind them. Whiteguard's collar is woven from ward-silk that provides protection against psychic attacks, essential equipment for a prophet who must look into the minds of those planning violence. They earned their blue hat by successfully predicting and preventing a series of assassination attempts during the post-Loyalty Wars period, using prophecy magic to identify threats before they became action.\n\nTheir magic is Protective Prophecy, seeing dangers before they manifest, predicting attacks in time to prepare defenses, and using future-sight to guide protective magic. Whiteguard's white fur makes them highly visible, but this actually enhances their protective role by serving as a beacon for those seeking safety. Their black eyes provide stark contrast that helps them focus on dark intentions and hidden threats. They serve as the Deep's security specialist, using prophecy to protect other Wizards from those who would harm them for their knowledge."},
    {"number": 6198, "name": null, "image": "images/dogs/6198.png", "traits": [["Background", "Purple"], ["Fur Color", "Gray"], ["Fur Pattern", "Tiger"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 6042, "title": "Ashstripe the Veil Ripper", "order": "Arcane", "realm": "Ember Wastes", "lore": "Before the Second Howl scarred the sky, there was a place in the Ember Wastes where reality had worn thin , a canyon of black glass where the ground still glowed from some ancient catastrophe. That is where Ashstripe was found, curled in the cooling ash like something the earth had forged rather than born.\n\nTheir gray Tiger-striped coat carries the pattern of the Wastes themselves , bands of charcoal and silver that shift in firelight like smoldering embers. Those black eyes hold no warmth. They hold something worse: clarity. Ashstripe sees through things. Not metaphorically. The veils that separate what is from what could be, what was from what should never have happened , Ashstripe tears them open with a precision that makes the other Arcane mages deeply uncomfortable.\n\nMost Arcane wizards study the boundaries between dimensions with careful reverence. Ashstripe studies them the way a surgeon studies anatomy: looking for the seams, the weak points, the places where one clean cut reveals everything hidden underneath. They were the first wizard in three centuries to successfully look behind the Veil of Pawtheon's founding and return sane. What they saw, they have never shared. But they stopped sleeping afterward, and sometimes in the dead Waste nights, the stripes on their fur glow faintly, as if lit from within by something that followed them back.\n\nThe Arcane Order wanted to censure them. Instead, they promoted them. Because when something breaks through from the other side , and in the Ember Wastes, things always eventually do , Ashstripe is the only one who can look at it without flinching, walk toward it without hesitating, and rip the veil shut behind it with their bare will.\n\nThey work alone. They prefer it that way. The Ember Wastes are unforgiving to the hesitant, and Ashstripe has no patience for wizards who flinch at what lies beneath the surface of the world. Their tower , if you can call a half-collapsed obsidian spire a tower , sits at the edge of the glass canyon, and the other wizards say you can see light flickering inside at hours when no fire should burn.\n\nAshstripe does not explain. Ashstripe does not comfort. Ashstripe rips the veil, looks at the truth, and deals with it. That is enough."},
    {"number": 6232, "name": null, "image": "images/dogs/6232.png", "traits": [["Background", "Yellow"], ["Fur Color", "Yellow"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 6043, "title": "Goldsolid the Pure Prophet", "order": "Deep", "realm": "Sunward Heights", "lore": "From the realm of pure colors and simple truths, Goldsolid brings Solid-breed clarity to the complex art of prophecy. Their yellow Solid fur creates perfect color purity with no distracting patterns, while their black eyes provide absolute focus on single-thread futures without the complications that multi-colored eyes create. They specialize in Simple Prophecy, clear, unambiguous visions of straightforward futures with minimal complications.\n\nTheir magic focuses on Pure Truth Prophecy, seeing futures without interpretation, bias, or wishful thinking. Goldsolid's visions are shorter but more accurate than other prophets', focusing on specific moments rather than complex storylines. Their Solid nature means they see one future at a time rather than the multiple probability streams that confuse other Deep Wizards. They serve as the Order's specialist in direct, actionable prophecy that can guide immediate decision-making without requiring extensive interpretation."},
    {"number": 6597, "name": null, "image": "images/dogs/6597.png", "traits": [["Background", "Red"], ["Fur Color", "Black"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Square Glasses"]], "rank": 6539, "title": "Inkwell the Archive Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "A scholarly prophet whose black fur absorbs magical energy without reflection, while their square glasses focus on detailed analysis of specific future events rather than broad prophetic sweeps. Blackglasses earned their position by developing techniques for archival prophecy, not just seeing what will happen, but creating permanent records of prophetic visions that can be studied and referenced later.\n\nTheir specialty is Documentation Prophecy, creating detailed, searchable records of prophetic visions, cross-referencing predictions to identify patterns in future-events, and maintaining the Deep's prophetic archives. Blackglasses' Classic stability provides the patience needed for long-term prophetic research, while their black fur helps them blend into the Tidewatch's underground environment. They serve as the Deep's institutional memory, ensuring that important prophecies aren't forgotten or misinterpreted over time."},
    {"number": 9017, "name": null, "image": "images/dogs/9017.png", "traits": [["Background", "Tan"], ["Fur Color", "Tan"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Yellow"]], "rank": 6598, "title": "Sleepysteady the Gentle Dreamer", "order": "Dream", "realm": "Violet Highlands", "lore": "Sleepysteady specializes in gentle dream-work during rest. Their tan fur and yellow eyes distinguish them in the current registry; their name describes their calm manner, not a Sleepy Eyes trait. They are one of the Dream Order's three Classic-patterned current bearers.\n\nThrough their magenta hat, Sleepysteady channels Roseglow into Gentle Dream Healing: shared rest, recovery and quiet support for willing sleepers. They work with consent and care, allowing exhausted packmates to rebuild trust without forcing intimacy. Ordinary sleep continues when Roseglow is new, but their magical healing does not."},
    {"number": 1271, "name": null, "image": "images/dogs/1271.png", "traits": [["Background", "Aqua"], ["Fur Color", "White"], ["Fur Pattern", "Collie"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 6653, "title": "Snowcollie the Patient Amplifier", "order": "Dream", "realm": "Deepwood", "lore": "Snowcollie's pristine white Collie fur stands out starkly in the dark Deepwood, a beacon of calm in the forest's perpetual twilight. Their patience is legendary even within the Dream Order , they will sit with a troubled soul for days, weeks, amplifying their capacity for self-compassion one gentle pulse at a time. Where other amplifiers work fast and loud, Snowcollie works slow and deep, building oneiroic resilience from the roots up. The Deepwood taught them this: the tallest trees grew the slowest, and the strongest hearts are built the same way."},
    {"number": 4042, "name": null, "image": "images/dogs/4042.png", "traits": [["Background", "Tan"], ["Fur Color", "Gray"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Pink"]], "rank": 6804, "title": "Roseflame the Pink Eyed", "order": "Flame", "realm": "Violet Highlands", "lore": "The third pink-eyed Flame Wizard, proving that oneiroic sight is more common in the Order than initially recognized. Roseflame's gray Classic appearance makes them blend into any crowd in the Violet Highlands, but their pink eyes reveal the oneiroic currents flowing beneath political discourse. They earned their orange hat during a Grand Assembly session when they stood up and used flame magic to literally illuminate the oneiroic dishonesty in several speakers' arguments.\n\nTheir power lies in Emotional Flame, fire that burns lies, cowardice, and dishonor while leaving truth, courage, and integrity untouched. In the politically complex Violet Highlands, this makes them both invaluable and dangerous. Roseflame serves as the Flame's truth-detector, using controlled fire to reveal when someone is lying to themselves as much as to others. Their gray fur and pink eyes create the perfect combination for seeing clearly through political smoke."},
    {"number": 6502, "name": null, "image": "images/dogs/6502.png", "traits": [["Background", "Yellow"], ["Fur Color", "White"], ["Fur Pattern", "Collie"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7031, "title": "Sleepyheart the Dream Bonder", "order": "Arcane", "realm": "Deepwood", "lore": "Sleepyheart, called the Dream Bonder, is an Arcane Wizard whose purple hat channels Umbra. Their title reflects a collaboration with Dream healers, not membership in the Dream Order. A White Collie from the Deepwood, with black eyes and no clothing, they study thresholds between waking space and dream space.\n\nAfter the Loyalty Wars, Sleepyheart helped Dream specialists work safely with traumatized packs. Their Arcane boundary wards stabilize access and guard sleeping bodies; Dream colleagues supply Roseglow's empathy and thread-healing. Sleepyheart cannot substitute Umbra for Roseglow or bypass either moon's new-moon limits. Controlled sleep is a working practice, not a Sleepy Eyes collection trait."},
    {"number": 4650, "name": null, "image": "images/dogs/4650.png", "traits": [["Background", "Tan"], ["Fur Color", "Tan"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7071, "title": "Sandstone the Stable Amplifier", "order": "Arcane", "realm": "Sunward Heights", "lore": "Sandstone's tan Solid coat is the exact color of the ancient stone towers that dot the Sunward Heights , so perfectly matched that they can press against a wall and vanish entirely. This is not camouflage magic; Sandstone simply belongs to this place so completely that the architecture claims them as its own. As the Arcane Order's amplification specialist, Sandstone takes weak magical signals and stabilizes them into usable power. They remove noise, strip interference, and deliver clean, pure magical energy. They are the foundation others build upon , unglamorous, essential, and quietly proud of it."},
    {"number": 5538, "name": null, "image": "images/dogs/5538.png", "traits": [["Background", "Tan"], ["Fur Color", "Gray"], ["Fur Pattern", "Solid"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7282, "title": "Graystorm the Weather Walker", "order": "Wild", "realm": "Sunward Heights", "lore": "From the eternally sunny Sunward Heights, Graystorm brings understanding of what plants need when the sun doesn't shine. Their gray Solid fur contrasts sharply with their homeland's bright environment, marking them as different from their sun-loving neighbors. They earned their green hat during the Great Silence, when even the sun seemed dim, by keeping food plants alive through forty-nine hours of magical darkness.\n\nTheir magic is Weather-Independent Botany, plants that thrive regardless of weather conditions, root systems that store nutrients for extended dry periods, and agricultural techniques that work during storms, droughts, or unnatural darkness. Graystorm serves as the Wild's insurance policy against climate disasters, maintaining emergency food sources that remain productive when normal agriculture fails. Their gray appearance reflects their specialty in working with plants during gray, overcast conditions when other Wild Wizards' magic is weakest."},
    {"number": 7257, "name": null, "image": "images/dogs/7257.png", "traits": [["Background", "Tan"], ["Fur Color", "Gray"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Sleepy"]], "rank": 7436, "title": "Graydreamer the Sleep Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "A Classic whose permanently sleepy appearance reflects their specialty in dream-state prophecy and unconscious vision work. Graydreamer's gray fur provides perfect neutrality for dream magic, while their sleepy eyes are actually processing multiple layers of prophetic information simultaneously. They earned recognition by successfully maintaining continuous prophetic surveillance through extended sleep periods, providing 24-hour future monitoring.\n\nTheir magic is Dream Prophecy, seeing futures through prophetic dreams, accessing visions that only appear during unconscious states, and maintaining prophetic awareness even while asleep. Graydreamer spends most of their time in controlled sleep states, conducting prophetic research in dream realms where normal physical limitations don't interfere with future-sight. They serve as the Deep's night shift, ensuring that prophetic monitoring continues even when other Wizards are sleeping."},
    {"number": 1053, "name": null, "image": "images/dogs/1053.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Zombie"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7607, "title": "Deathforge the Undying", "order": "Flame", "realm": "Shadowmire", "lore": "The darkest Wizard in the entire Order of 86, both literally and figuratively. A Zombie from the Shadowmire practicing fire magic, decay and transformation meeting flame and renewal. Deathforge earned their orange hat by walking through the Great Rot's infected territory and emerging not just unharmed, but changed. The corruption that destroys other living things feeds their Zombie nature, and they learned to burn rot away from the inside out.\n\nTheir all-black appearance, black fur, black eyes, black pattern, makes them invisible in smoke and shadow. But when Deathforge channels flame magic, their entire body glows from within like a coal in the darkness. They represent the Flame's answer to corruption: sometimes the only way to cleanse decay is to burn it from someone already adapted to this corruption. Their death-touched nature makes them immune to many forms of magical attack, while their flame magic provides the offensive power that pure immunity lacks. When the Great Rot finally breaks containment, Deathforge will be the Flame's first response."},
    {"number": 3479, "name": null, "image": "images/dogs/3479.png", "traits": [["Background", "Green"], ["Fur Color", "Beige"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7641, "title": "Dawnheart the Neutral Amplifier", "order": "Dream", "realm": "Violet Highlands", "lore": "Dawnheart's beige Classic coat is the color of first light breaking over the Violet Highlands , warm, neutral, promising. In the Dream Order, where oneiroic magic runs hot and personal, Dawnheart is the rare neutral party. Their amplification magic doesn't favor any particular subconscious current; it strengthens whatever is truest in a being's heart, whether that's love, grief, courage, or quiet contentment. This neutrality makes them invaluable as a mediator between Orders and an amplifier whose boost carries no agenda. Dawnheart simply makes you more of what you already are."},
    {"number": 3735, "name": null, "image": "images/dogs/3735.png", "traits": [["Background", "Yellow"], ["Fur Color", "Pink"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7823, "title": "Roseheart the Steady Bond", "order": "Dream", "realm": "Violet Highlands", "lore": "Roseheart's pink Classic coat is the rarest color in the Violet Highlands , a soft blush against the grey stone and purple heather. Their black eyes hold a steadiness that calms even the most fractured spirits. In the Dream Order, where oneiroic magic can be volatile, Roseheart is the anchor. They specialize in dream-bonding magic , not the dramatic kind that forges instant connections, but the quiet, patient kind that strengthens existing bonds until they become unbreakable. Years later, when friendships survive betrayal and love survives distance, Roseheart's magic is the invisible architecture holding it all together."},
    {"number": 9624, "name": null, "image": "images/dogs/9624.png", "traits": [["Background", "Tan"], ["Fur Color", "Black"], ["Fur Pattern", "Spotted"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 7914, "title": "Inkspot the Silent Decoder", "order": "Arcane", "realm": "Deepwood", "lore": "Inkspot's dark Spotted coat makes them nearly invisible in the shadowed Deepwood, where dappled light creates natural camouflage for their black-on-black markings. Those black eyes absorb information the way their fur absorbs light , completely, silently, without reflection. The Arcane Order's master decoder, Inkspot can unravel any cipher, any ward, any enchantment designed to conceal. They don't break codes through brute force but through patient observation, finding the single spot , the one flaw in every pattern , that unravels the whole design. Their name is whispered, never shouted. Their work is felt, never seen."},
    {"number": 1841, "name": null, "image": "images/dogs/1841.png", "traits": [["Background", "Green"], ["Fur Color", "Orange"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 8023, "title": "Ember Beard the Bridge Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "Ember Beard earned their name from the flame-orange Classic fur that frames their face like a burning corona. In the misty Violet Highlands, where the boundary between the seen and unseen grows thin, Ember Beard stands at the crossings between worlds and speaks prophecy. Their black eyes reflect nothing , they absorb light and return visions. The Deep Order sends their most troubled seekers to Ember Beard, who builds bridges of understanding between what a soul fears and what it needs to face. No temple, no tower , just a dog standing at the edge of a cliff, fur blazing orange against the violet sky, speaking truths that rearrange the listener's entire life."},
    {"number": 9713, "name": null, "image": "images/dogs/9713.png", "traits": [["Background", "Rose"], ["Fur Color", "Black"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 8952, "title": "Darkleaf the Shadow Grower", "order": "Wild", "realm": "Violet Highlands", "lore": "The least common Wild Wizard, ranking very low in the collection but serving a crucial role in the Order. Darkleaf's all-black appearance makes them nearly invisible in deep forest shadows, while their Classic stability provides the patience needed for deep-shade botany. They specialize in Under-Story Magic, the plants that grow beneath forest canopies, in the shadow of larger trees, creating the complex ecosystem layers that support forest health.\n\nTheir magic focuses on Symbiotic Growth, plants that support each other through root networks, leaf-litter cycles that enrich soil, and the delicate balance of competition and cooperation that keeps forests healthy. Darkleaf tends the forest floor, ensuring that nutrients cycle efficiently from fallen leaves back into growing trees. They prove that Wild magic doesn't require flashy displays, sometimes the most important growth happens quietly, in darkness, where only patient eyes can see."},
    {"number": 3417, "name": null, "image": "images/dogs/3417.png", "traits": [["Background", "Tan"], ["Fur Color", "Orange"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 9083, "title": "Orangeshield the Flame Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "The second orange-furred Deep Wizard, but where Orangeclassic focuses on Order relations, Orangeshield specializes in fire-related prophecy. Their orange fur creates sympathetic resonance with fire magic, allowing them to predict volcanic eruptions, magical fire accidents, and Flame Order activities with unusual accuracy. Their black eyes provide the cool focus needed to observe fire futures without being overwhelmed by their intensity.\n\nTheir magic is Elemental Opposition Prophecy, using water magic to predict fire events, finding the points where opposing forces create prophetic clarity, and reading futures in the tension between incompatible elements. Orangeshield's orange coloring shouldn't work with water magic, but the contradiction actually enhances their prophetic ability by providing unique perspective on elemental interactions. They serve as early warning system for fire-related disasters throughout Pawtheon."},
    {"number": 7226, "name": null, "image": "images/dogs/7226.png", "traits": [["Background", "Tan"], ["Fur Color", "Tan"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 9172, "title": "Tanwatcher the Patient Prophet", "order": "Deep", "realm": "Violet Highlands", "lore": "The lowest-ranking Deep Wizard, but ranking means nothing when prophecy is the goal. Tanwatcher's tan Classic fur provides perfect camouflage in earthtone environments, while their black eyes maintain absolute focus on long-term prophetic patterns that other Wizards find too boring to track. They specialize in Patient Prophecy, following probability threads for years or decades to see how small changes create major outcomes.\n\nTheir magic focuses on Long-Term Vision, seeing the consequences of current decisions decades into the future, tracking the slow development of major historical changes, and maintaining prophetic vigilance over trends too gradual for other prophets to notice. Tanwatcher's Classic stability provides the mental endurance needed for prophetic projects that span multiple lifetimes. They serve as the Deep's specialist in civilizational prophecy, predicting the rise and fall of governments, cultural changes, and the long-term consequences of magical development."},
    {"number": 3186, "name": null, "image": "images/dogs/3186.png", "traits": [["Background", "Tan"], ["Fur Color", "Brown"], ["Fur Pattern", "Classic"], ["Head", "Wizard"], ["Eyes", "Black"]], "rank": 9281, "title": "Brownheart the Common Light", "order": "Radiant", "realm": "Violet Highlands", "lore": "The least rare Wizard in the entire Order of 86, ranking 9,281 out of 10,000, more common than 92.8% of all Doginal Dogs. Yet Brownheart practices the magic of absolute truth and divine light. Their brown Classic fur is completely ordinary, their black eyes provide simple focus, and they wear no distinctive clothing or accessories. They are the most unremarkable-looking being practicing the most remarkable magic.\n\nTheir power lies not in spectacular displays but in Simple Truth, basic, honest light that reveals reality without interpretation or complication. Brownheart's magic doesn't blind or overwhelm; it simply shows things as they actually are. Their ordinary appearance makes them approachable to common dogs who would be intimidated by more dramatic Radiant Wizards. They serve as the Order's connection to everyday truth-telling, proving that the most important light isn't the brightest, it's the most reliable. When other Radiant magic fails, Brownheart's simple illumination still works."}
];

window.wizardName = function (w) { return w.title || w.name || ("Dog #" + w.number); };
window.findWizard = function (n) {
  for (var i = 0; i < WIZARDS.length; i++) if (WIZARDS[i].number === n) return i;
  return -1;
};
